"""Build the local release entry, using kit typography and documentation styles."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=''
for theme in ('tide','summer','bumble'):
    rows+=f'<article class="tide-doc-panel tide-stack"><p class="tide-eyebrow">{theme.title()}</p><h2>{theme.title()} / paired modes</h2><p>Identical structure, components and spacing. Semantic palette roles adapt the canvas and every surface.</p>'
    for mode in ('light','dark'):
        rows+=f'<div class="tide-row"><a class="tide-button tide-button--secondary" href="kit/{theme}-{mode}/index.html#components">{mode.title()} UI kit</a><a class="tide-link" href="kit/{theme}-{mode}/frames/filter-panel.html">{mode.title()} filter examples</a></div>'
    rows+='</article>'
html='''<!doctype html><html lang="en" data-theme="tide" data-mode="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tide 1.3.0 · Shared filter release</title><link rel="stylesheet" href="kit/css/tide.css"><link rel="stylesheet" href="kit/css/docs.css"></head><body class="tide tide-screen tide-screen--kit"><a class="tide-skip-link" href="#release">Skip to release</a><main class="tide-page-body tide-page-body--spaced tide-stack" id="release"><header class="tide-stack"><p class="tide-eyebrow">Tide / kit 1.3.0</p><h1>One shared filter panel.</h1><p>The approved interaction now has a component home. The kit owns the shell; the app owns its behavior and placement.</p><div class="tide-row"><a class="tide-button" href="app/index.html?preview-filters=open">Test the app copy</a><a class="tide-button tide-button--secondary" href="kit/bumble-dark/index.html#components">Explore the new kit</a></div></header><div class="tide-doc-grid">'''+rows+'''</div><section class="tide-doc-panel tide-stack"><h2>What shipped</h2><ul><li>Optional header, independently scrolling body and pinned footer.</li><li>Existing buttons, fields, choices, badges, validation and empty states.</li><li>One combined GET form; live draft counts; Reset, Cancel and Clear contracts.</li><li>All six themes/modes; registered HTML/CSS/state sources and integration guidance.</li></ul><p><a class="tide-link" href="kit/docs/SEARCH-FILTERS.md">Read the integration contract</a> · <a class="tide-link" href="docs/ADOPTION.md">See the extraction map</a> · <a class="tide-link" href="qa/BROWSER.md">Browser evidence</a></p></section><section class="tide-notice"><strong>Approved prototype preserved</strong><p>Unified Search 1.0.2, kit 1.2.1, the previous app and all earlier studies remain unchanged. The copy keeps desktop geometry, native scrollbar spacing and the mobile/tablet flyout.</p><p><a class="tide-link" href="../margin-reveal-unified-search/demo/index.html">Open preserved prototype</a> · <a class="tide-link" href="qa/verification.json">Preservation and adoption checks</a></p></section><p class="tide-caption">Local release · Actual Chromium checks recorded separately. Firefox/Safari and physical-device checks remain deferred.</p></main></body></html>'''
html=html.replace('<body class="tide tide-screen tide-screen--kit">','<body class="tide tide-release-review">')
html=html.replace('<main class="tide-page-body tide-page-body--spaced tide-stack" id="release">','<main id="release" class="tide-release-review__main tide-page-body tide-stack">',1)
html=html.replace('</head>','<link rel="stylesheet" href="review.css"></head>')
html=html.replace('class="tide-doc-grid"','class="tide-release-review__themes"',1)
html=html.replace('Read the integration contract</a>', 'Read the integration contract</a> · <a class="tide-link" href="kit/dist/tide-ui-kit-1.3.0.zip">Download kit 1.3.0</a>')
(ROOT/'index.html').write_text(html+'\n',encoding='utf-8',newline='\n')
print('Release review built.')
